import {CURRENT_ID,CURRENT_URL,CURRENT_EMBED_URL,embedMap,ARCHIVE_URL,OWNERS,parseArchives,validateFeed,validateTerritories,chooseSnapshot,shiftTime,CONTROL,safeUrl} from './core.mjs';
const $ = id => document.getElementById(id);
let view='current', step='month', archives=[], catalogLive=false, feed=null, target=null, map=null, overlay=null, sequence=0, playTimer=null, toastTimer=null, refreshing=false, currentModified=null;
let currentEmbed=CURRENT_EMBED_URL, cutoffVerified=false, historyPeriod=null;
let config={authorizedFeedUrl:null,pollIntervalSeconds:60}, lastCutoff=null, lastCheck=null;
const formatTime = value => new Intl.DateTimeFormat('zh-CN',{timeZone:'UTC',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value))+' UTC';
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
async function json(url,maxBytes=5*1024*1024){const r=await fetch(url,{signal:AbortSignal.timeout(20000),cache:'no-store',credentials:'omit'});if(!r.ok)throw new Error(`服务返回 HTTP ${r.status}`);const declared=Number(r.headers.get('content-length'));if(declared>maxBytes)throw new Error('数据超过加载上限');const text=await r.text();if(new TextEncoder().encode(text).byteLength>maxBytes)throw new Error('数据超过加载上限');const body=JSON.parse(text);if(body.error)throw new Error('来源接口返回错误');return body;}
function notify(title,body){$('notice-title').textContent=title;$('notice-body').textContent=body;$('map-notice').hidden=false;}
function clearNotice(){$('map-notice').hidden=true;}
function sourceStatus(title,detail,error=false){$('source-status').textContent=title;$('source-detail').textContent=detail;$('availability').classList.toggle('error',error);}
function stopPlayback(){clearInterval(playTimer);playTimer=null;$('play').textContent='播放';}
function showOfficial(url,title){sequence++;stopPlayback();clearNotice();$('official-map').hidden=false;$('independent-map').hidden=true;$('official-map').src=url;$('official-map').title=title;$('original').href=url.includes('/apps/Embed/')?CURRENT_URL:url.split('#')[0];$('original').hidden=false;}
function renderArchives(){
 const year=Number($('year').value);const months=new Map();for(const item of archives.filter(a=>a.year===year)){if(!months.has(item.month))months.set(item.month,item);}
 $('archive-count').textContent=`${months.size} / 12 个月有已核验的档案链接${catalogLive?'':' · 本地目录，未实时核验'}`;
 $('month-grid').replaceChildren();
 for(let month=1;month<=12;month++){const item=months.get(month);const button=document.createElement('button');button.textContent=`${month} 月`;button.className=item?'available':'unavailable';button.title=item?item.title:'当前目录没有该月档案；可查看完整官方档案';button.setAttribute('aria-label',`${year} 年 ${month} 月${item?'：打开档案':'：无可用档案'}`);button.setAttribute('aria-disabled',String(!item));button.addEventListener('click',()=>{if(!item){toast(`${year} 年 ${month} 月没有可用档案，不会展示其他时间的战线。`);return;}historyPeriod=`${year} 年 ${month} 月 · 精确日期见原图时间条`;view='history';updateView();showOfficial(item.url,`ISW ${year} 年 ${month} 月原始历史地图`);$('map-title').textContent=`${year} 年 ${month} 月 · 历史评估`;$('viewer-status').textContent='在发布方地图内部使用日期条查看真实快照。';$('timeline-note').textContent='正在查看该月的原始历史地图。精确日期与回放由发布方时间条控制，页面没有小时级数据。';document.querySelectorAll('.month-grid button').forEach(b=>b.classList.remove('selected'));button.classList.add('selected');});$('month-grid').append(button);}
}
function initYears(){const before=$('year').value;const current=new Date().getUTCFullYear();$('year').replaceChildren();for(let y=current;y>=2022;y--){const option=document.createElement('option');option.value=String(y);option.textContent=`${y} 年`;$('year').append(option);}if(before)$('year').value=before;renderArchives();}
function updateView(){
 $('timeline-note').textContent=view==='licensed'?'步长只改变目标时间。仅展示来源声明有效的真实快照，历史缺口保持空白。':'月 / 年用于浏览档案。日 / 周回放请使用原图内的时间条；没有小时级数据时不生成小时级战线。';
 document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});
 $('archive-controls').hidden=view==='licensed';$('snapshot-controls').hidden=view!=='licensed';$('timeline-title').textContent=view==='licensed'?'浏览实际发布的授权快照':'选择已发布的历史档案';
 $('view-label').textContent=view==='current'?'最新公开评估':view==='history'?'历史公开评估':'授权数据 · 独立绘图';
 $('ua-label').textContent=view==='licensed'?'乌方评估控制区域':'乌方活动 / 反攻相关区域';
 $('legend-note').textContent=view==='licensed'?'俄方红色、乌方蓝色；声称范围用虚线且不填充。未知及争议区域单独标记。未提供的区域保持空白。':'原图采用发布方图例；蓝色活动范围不等于已确认实控。未着色区域也不能直接推断为另一方控制。';
 $('cutoff').textContent=view==='licensed'?(feed?.snapshots.length?formatTime(feed.snapshots.at(-1).observed):'没有授权快照'):(view==='history'?(historyPeriod||'以原图中的历史日期为准'):(lastCutoff?(lastCutoff+(cutoffVerified?'':'（本地记录，待核验）')):'未获取；请查看原图日期'));
 $('resolution').textContent=view==='licensed'?(feed?.source.temporalResolution==='hour'?'来源声明小时级':feed?'来源声明日级 / 不规则':'尚未接入授权数据'):'按发布方评估 / 通常每日';
 document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.step===step)));
}
function setView(next){if(!['current','history','licensed'].includes(next))throw new Error('未知视图');view=next;if(view==='history')historyPeriod=null;updateView();if(view==='current'){showOfficial(currentEmbed,'ISW 发布方原始俄乌战线地图');$('map-title').textContent='乌克兰及周边战区';$('viewer-status').textContent='原图由发布方加载；嵌入空白时可打开原图。';}else if(view==='history'){showOfficial(ARCHIVE_URL,'ISW 完整原始历史档案');$('map-title').textContent='俄乌战争 · 历史档案';$('viewer-status').textContent='选择下方月份或在官方完整档案中浏览。';}else{sequence++;stopPlayback();$('official-map').hidden=true;$('independent-map').hidden=false;$('original').hidden=!feed;if(feed)$('original').href=feed.source.url;$('map-title').textContent=feed?.source.name||'独立实控地图 · 待接入';$('viewer-status').textContent=feed?'绘图来源及授权依据由维护者核验。':'没有授权数据时保持空白，不生成示意战线。';ensureMap();if(feed?.snapshots.length)renderSnapshot(target??feed.snapshots.at(-1).observed);else{if(overlay){overlay.remove();overlay=null;}notify('尚未接入授权战线数据','这里已支持红蓝实控区、争议区和真实历史快照。现在可先查看 ISW 原图及已发布档案；没有数据不会绘制实控范围。');}}}
function ensureMap(){if(!window.L){notify('地图库尚未加载','请刷新页面后重试。');return;}if(!map){map=L.map('independent-map',{center:[48.5,33.6],zoom:6,zoomControl:true});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:17,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>'}).addTo(map);}setTimeout(()=>map.invalidateSize(),0);}
async function renderSnapshot(time){
 target=time;const token=++sequence;stopPlaybackIfInvalid();$('target-time').value=new Date(time).toISOString().slice(0,16);if(overlay){overlay.remove();overlay=null;}clearNotice();
 const snapshot=feed&&chooseSnapshot(feed.snapshots,time);
 if(!snapshot){notify('这个时间没有有效快照','只显示来源在该时间有效的记录。不会沿用过期边界、展示未来快照或插值填补空白。');$('snapshot-label').textContent=`目标：${formatTime(time)} · 无有效快照`;$('cutoff').textContent='目标时间无有效数据';return;}
 $('snapshot-label').textContent=`目标：${formatTime(time)} · 加载快照…`;
 try{const geojson=validateTerritories(await json(snapshot.geojsonUrl,16*1024*1024));if(token!==sequence||view!=='licensed')return;ensureMap();if(!map)throw new Error('地图库不可用');overlay=L.geoJSON(geojson,{style:f=>{const claimed=f.properties.assessment==='claimed';return {color:CONTROL[f.properties.control].color,weight:1.8,fillOpacity:claimed?0:f.properties.control==='disputed'?.2:.36,dashArray:claimed||f.properties.control==='disputed'?'5 5':undefined};},onEachFeature:(f,layer)=>{const box=document.createElement('div');const heading=document.createElement('strong');heading.textContent=CONTROL[f.properties.control].label;box.append(heading);for(const line of [f.properties.assessment==='claimed'?'来源声称，未标为已确认控制':'来源评估',f.properties.name||'',`快照：${formatTime(snapshot.observed)}`,`来源：${feed.source.name}`]){const p=document.createElement('div');p.textContent=line;box.append(p);}layer.bindPopup(box);}}).addTo(map);
 $('cutoff').textContent=formatTime(snapshot.observed);$('snapshot-range').value=String(feed.snapshots.indexOf(snapshot));$('snapshot-label').textContent=`评估：${formatTime(snapshot.observed)} · 发布：${formatTime(snapshot.published)} · 覆盖：${snapshot.coverage}${geojson.features.length?'':' · 来源返回空区域集'}`;
 }catch(e){if(token!==sequence||view!=='licensed')return;notify('无法加载这条快照',e.message);$('snapshot-label').textContent=`目标：${formatTime(time)} · 加载失败，未显示旧战线`;}
}
function stopPlaybackIfInvalid(){if(!feed?.snapshots.length)stopPlayback();}
function move(direction){if(!feed?.snapshots.length){toast('需要先接入带时间戳的授权快照。');return;}if(step==='hour'&&feed.source.temporalResolution!=='hour'){toast('来源没有声明小时级数据，无法按小时回放。');stopPlayback();return;}const latest=feed.snapshots.at(-1).observed;const earliest=feed.snapshots[0].observed;const next=Math.min(latest,Math.max(earliest,shiftTime(target??latest,step,direction)));if(next===target){stopPlayback();return;}renderSnapshot(next);}
async function checkSources(manual=false){
 if(refreshing)return;refreshing=true;$('refresh').disabled=true;
 try{const [item,data]=await Promise.all([json(`https://www.arcgis.com/sharing/rest/content/items/${CURRENT_ID}?f=json`),json(`https://www.arcgis.com/sharing/rest/content/items/${CURRENT_ID}/data?f=json`)]);if(!OWNERS.has(item.owner?.toLowerCase())||item.type!=='StoryMap'||item.access!=='public')throw new Error('发布方身份或公开访问状态与已核验来源不符');
 const cutoff=Object.values(data.nodes||{}).map(n=>n.data?.text||'').find(t=>/^Assessed Control of Terrain in Ukraine\s+as of /i.test(t));lastCutoff=cutoff?cutoff.replace(/^Assessed Control of Terrain in Ukraine\s+as of\s*/i,'').replace(/<[^>]*>/g,'').trim():null;
 cutoffVerified=true;lastCheck=new Date().toISOString();$('checked').textContent=formatTime(lastCheck);if(view==='current')$('cutoff').textContent=lastCutoff||'未取得评估截止；请核对原图';
 const mapResource=Object.values(data.resources||{}).find(r=>r.type==='webmap'&&/^[a-f0-9]{32}$/.test(r.data?.itemId));if(mapResource)currentEmbed=embedMap(mapResource.data.itemId);
 const changed=currentModified!==null&&currentModified!==item.modified;currentModified=item.modified;sourceStatus(changed?'来源页面有新版本':'来源已连接',`原始项目修改：${formatTime(item.modified)}。此时间不是实控变化时间。`);if(changed&&view==='current'){showOfficial(currentEmbed,'ISW 发布方原始俄乌战线地图');toast('来源页面已更新，正在重新加载原图。');}else if(manual)toast('已检查来源。评估时间见左侧，刷新不代表出现新战线。');
 }catch(e){sourceStatus('来源检查失败',`${e.message}。最后成功检查：${lastCheck?formatTime(lastCheck):'无'}；当前内容未核验为最新。`,true);if(manual)toast('无法核查最新版本，可打开原图或稍后重试。');}
 try{const q='('+[...OWNERS].map(owner=>`owner:${owner}`).join(' OR ')+') AND Ukraine AND type:"Web Experience"';const all=[];let start=1;for(let page=0;page<5;page++){const data=await json(`https://www.arcgis.com/sharing/rest/search?${new URLSearchParams({f:'json',q,num:'100',start:String(start)})}`);all.push(...(data.results||[]));if(!data.nextStart||data.nextStart<0)break;start=data.nextStart;}const found=parseArchives(all);if(found.length){archives=found;catalogLive=true;renderArchives();}}catch{catalogLive=false;renderArchives();}
 if(config.authorizedFeedUrl){try{const data=validateFeed(await json(safeUrl(config.authorizedFeedUrl,location.href),8*1024*1024),Date.now(),safeUrl(config.authorizedFeedUrl,location.href));const old=feed?.snapshots.at(-1)?.id;feed=data;$('snapshot-range').max=String(Math.max(0,feed.snapshots.length-1));const liveTarget=target===null||target===feed.snapshots.find(s=>s.id===old)?.observed;if(view==='licensed'){updateView();if(!feed.snapshots.length){sequence++;if(overlay){overlay.remove();overlay=null;}notify('来源没有快照','授权接口未返回历史记录，地图保持空白。');}else if(liveTarget||old!==feed.snapshots.at(-1)?.id)await renderSnapshot(liveTarget?feed.snapshots.at(-1).observed:target);}}catch(e){if(view==='licensed'){sequence++;if(overlay){overlay.remove();overlay=null;}notify('授权数据检查失败',`${e.message}。当前地图已清空，避免将旧数据当成最新。`);}toast('授权数据无法更新：'+e.message);}}
 refreshing=false;$('refresh').disabled=false;
}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));
document.querySelectorAll('[data-step]').forEach(button=>button.addEventListener('click',()=>{const next=button.dataset.step;if(view!=='licensed'&&['hour','day','week'].includes(next)){toast(next==='hour'?'公开来源没有小时级实控快照，不生成小时级战线。':'日 / 周回放请在所选月份的发布方原图内部操作时间条。');return;}step=next;document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});if(view==='licensed')$('timeline-note').textContent='步长只改变目标时间。地图只显示来源声明在该时间有效的快照；缺口保持空白。';else if(next==='year')$('year').focus();}));
$('year').addEventListener('change',renderArchives);$('archive-index').addEventListener('click',()=>{historyPeriod=null;view='history';updateView();showOfficial(ARCHIVE_URL,'ISW 完整原始历史档案');$('map-title').textContent='完整官方历史档案';});
$('refresh').addEventListener('click',()=>checkSources(true));$('sources-button').addEventListener('click',()=>$('source-dialog').showModal());$('source-dialog').addEventListener('click',e=>{if(e.target===$('source-dialog'))$('source-dialog').close();});
$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('map-region').requestFullscreen();}catch{toast('当前浏览器不支持全屏，可打开原图。');}});
$('previous').addEventListener('click',()=>{stopPlayback();move(-1);});$('next').addEventListener('click',()=>{stopPlayback();move(1);});$('latest').addEventListener('click',()=>{stopPlayback();if(feed?.snapshots.length)renderSnapshot(feed.snapshots.at(-1).observed);else toast('没有授权快照。');});
$('apply-time').addEventListener('click',()=>{stopPlayback();const time=Date.parse($('target-time').value+'Z');if(!Number.isFinite(time))return toast('请选择有效的 UTC 时间。');renderSnapshot(time);});$('snapshot-range').addEventListener('input',()=>{stopPlayback();const s=feed?.snapshots[Number($('snapshot-range').value)];if(s)renderSnapshot(s.observed);});
$('play').addEventListener('click',()=>{if(playTimer)return stopPlayback();if(!feed?.snapshots.length)return toast('没有可播放的授权快照。');if(step==='hour'&&feed.source.temporalResolution!=='hour')return toast('来源没有小时级数据。');if(target===null||target>=feed.snapshots.at(-1).observed)renderSnapshot(feed.snapshots[0].observed);$('play').textContent='暂停';playTimer=setInterval(()=>move(1),2200);});
async function init(){try{config={...config,...await json('/data-config.json')};}catch{}try{const seed=await json('/catalog.json');archives=seed.archives||[];if(seed.cutoff){lastCutoff=seed.cutoff;$('cutoff').textContent=seed.cutoff+'（本地记录，待核验）';}}catch{}initYears();updateView();await checkSources();setInterval(()=>{if(!document.hidden)checkSources();},Math.max(60,Number(config.pollIntervalSeconds)||60)*1000);}
init();
if(navigator.onLine===false)sourceStatus('浏览器离线','ESP32 网页可打开，但外部地图和档案需要互联网。',true);
window.addEventListener('offline',()=>{sourceStatus('浏览器离线','外部地图及历史档案暂时无法更新。',true);if(view==='licensed'){sequence++;if(overlay){overlay.remove();overlay=null;}notify('浏览器离线','无法核验授权数据，已停止展示实控区域。');}stopPlayback();});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_map_state',description:'读取地图视图及来源核查状态，不推断实际战场控制。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({view,step,lastCheck,lastCutoff,catalogLive,authorizedSnapshots:feed?.snapshots.length||0})},{name:'select_map_view',description:'切换最新原图、历史档案或授权独立地图。独立地图没有数据时显示空状态。',inputSchema:{type:'object',properties:{view:{enum:['current','history','licensed']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length!==1)throw new Error('Invalid input');setView(input.view);return {view};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
